; The New Zealand Story - the enhanced game (enhanced/README.md).
; Edited by hand since October 2026; made from original/nzs_main.s by
; enhanced/tools/fork_source.py. Assembled by enhanced/tools/build_disk.py.
;
; The New Zealand Story (Ocean 1989, Amiga conversion by Choice Software:
; code C. Gordon, graphics S. Connor) - main program
;
; Packed on tracks 94-143; the track 90 loader unpacks it to $400 and jumps to $400.
; Assemble: vasmm68k_mot -Fbin -m68000 -no-opt -o main.bin nzs_main.s
;
; Block 1 is stored 4 bytes above where it runs: the bra.w below goes to Relocate, which
; moves it down to $400. It has its own org so its labels carry the run addresses while vasm
; writes the bytes contiguously.

	include	"nzs_hw.i"
	include	"nzs_equates.i"
	include	"ext.i"

	section	main,code
	org	$400
	bra.w	Relocate			; file $0000
Block1_Stored:					; block 1 as loaded (file $0004)

;===============================================================================
; Block 1: stored at $404, runs at $400-$320F after Relocate
;===============================================================================
	org	$400
Block1:

;-------------------------------------------------------------------------------
; JT_Init - The jump table at $400 (block 1): six bra.w the rest of the program calls through fixed
; addresses - Init, KeyTest, ReadJoystick, TrackRead, TrackWrite, GetKey. JT_Init is also the top
; of the stack (the stack grows down from $400).
;-------------------------------------------------------------------------------
JT_Init:
        bra.w   Init                            ; 00400

;-------------------------------------------------------------------------------
; JT_KeyTest - Jump table: KeyTest (d0 = raw key code -> Z clear if held).
;-------------------------------------------------------------------------------
JT_KeyTest:
        bra.w   KeyTest                         ; 00404

;-------------------------------------------------------------------------------
; JT_ReadJoystick - Jump table: ReadJoystick (called from the vertical blank).
;-------------------------------------------------------------------------------
JT_ReadJoystick:
        bra.w   ReadJoystick                    ; 00408

;-------------------------------------------------------------------------------
; JT_TrackRead - Jump table: TrackRead (d0 = track, d1 = tracks, a0 = where, d2 = drive).
; LoadTracks reads every level through it.
;-------------------------------------------------------------------------------
JT_TrackRead:
        bra.w   TrackRead                       ; 0040C

;-------------------------------------------------------------------------------
; JT_TrackWrite - Jump table: TrackWrite (only the monitor's W command uses it).
;-------------------------------------------------------------------------------
JT_TrackWrite:
        bra.w   TrackWrite                      ; 00410

;-------------------------------------------------------------------------------
; JT_GetKey - Jump table: GetKey (-> d0 = the lowest held key's character). After it, the system
; layer's variables: the drive last used ($420), the text cursor ($422 column, $424 line, as words;
; $423 / $425 as bytes for the printers), and TrackRead's 308-byte sector header buffer ($426).
; Enhanced: the TrackRead buffer at $426 is the enhanced game's header instead (ext.i:
; GAME_HEADER): the extension module writes the machine description and the boot drive there.
;-------------------------------------------------------------------------------
JT_GetKey:
        bra.w   GetKey                          ; 00414
dat_00418:
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00
dat_00420:
	dc.b	$FF,$FF
dat_00422:
	dc.b	$00
dat_00423:
	dc.b	$00
dat_00424:
	dc.b	$00
dat_00425:
	dc.b	$00
; enhanced: the original TrackRead's buffer ($426, 308 bytes) is the enhanced game's header, at
; a fixed address: the extension module writes the machine description and the boot drive here
; when it has unpacked the game (ext.i: GAME_HEADER)
EnhHeader:
	dc.b	'NZSE'
BootDrive:      dc.l    0                       ; the drive booted from
EnhMachine:     dcb.b   MI_SIZE,0               ; the machine description (ext.i)
	dcb.b	308-(*-EnhHeader),0
	ifne	EnhHeader-GAME_HEADER
	fail	EnhHeader must be at GAME_HEADER (ext.i)
	endc

;-------------------------------------------------------------------------------
; Init - entered from the jump table after Relocate: interrupts off, then a privilege violation
; that lands in sub_00576 in supervisor mode (vector $20 pointed there first: the program may be
; entered in user mode).
;-------------------------------------------------------------------------------
Init:
        lea.l   CUSTOM,a0                       ; 0055A
        move.w  #$7fff,(CUSTOM+INTENA).l        ; 00560
        move.l  #sub_00576,$20.l                ; 00568
        ori.w   #$700,sr                        ; 00572

;-------------------------------------------------------------------------------
; sub_00576 - SysStart - the system layer's start-up. Builds the monitor's text screen line table
; (dat_03110: 25 lines of $140 bytes), points ExecBase ($4) at a fake exec library (dat_02F9E) with
; its checksum, points every exception vector at sub_0158C (keeping the trace vector, $24), the
; interrupt autovectors at UnusedInterrupt and trap #14 at ErrorTrap, turns both drives' motors off
; and sets a6 to the saved PC (dat_031D8). Then l_0062C: the keyboard on (sub_011AE) and sub_0158C,
; which jumps to mon_GoAddress - GameStart ($4000): the game. The debug monitor's prompt (l_00644:
; registers, then each command key through sub_0069E) is reached only from the exception handlers
; and the keyboard's break key, never in play; its last command (l_00678) jumps into Kickstart
; ($F80000).
; Enhanced: EnhInit is called too (enhanced.s: the frames, the file cache, the title's lines); the
; debug monitor is gone - its prompt, commands and Kickstart exit with it.
;-------------------------------------------------------------------------------
sub_00576:
        lea.l   JT_Init(pc),a7                  ; 00576
        clr.l   d0                              ; 0057A
        lea.l   dat_03110(pc),a0                ; 0057C
        moveq   #$18,d1                         ; 00580
l_00582:
        move.l  d0,(a0)+                        ; 00582
        addi.l  #$140,d0                        ; 00584
        dbra    d1,l_00582                      ; 0058A
        ori.w   #$700,sr                        ; 0058E
        move.l  #dat_02F9E,$4.w                 ; 00592
        lea.l   dat_02FC2(pc),a0                ; 0059A
        move.w  #$17,d0                         ; 0059E
        moveq   #$0,d1                          ; 005A2
l_005A4:
        add.w   (a0)+,d1                        ; 005A4
        dbra    d0,l_005A4                      ; 005A6
        neg.w   d1                              ; 005AA
        addi.w  #$ffff,d1                       ; 005AC
        move.w  d1,(dat_02FC0).l                ; 005B0
        movea.l (V_Trace).w,a2                  ; 005B6
        lea.l   $8(pc),a0                       ; 005BA
        lea.l   sub_0158C(pc),a1                ; 005BE
        move.w  #$7d,d0                         ; 005C2
l_005C6:
        move.l  a1,(a0)+                        ; 005C6
        dbra    d0,l_005C6                      ; 005C8
        move.l  a2,(V_Trace).w                  ; 005CC
        move.l  #UnusedInterrupt,(V_Level1).w   ; 005D0
        move.l  #UnusedInterrupt,(V_Level3).w   ; 005D8
        move.l  #UnusedInterrupt,(V_Level4).w   ; 005E0
        move.l  #UnusedInterrupt,(V_Level5).w   ; 005E8
        move.l  #UnusedInterrupt,(V_Level6).w   ; 005F0
        move.l  #UnusedInterrupt,(V_Level7).w   ; 005F8
        move.w  #$1,(trk_Drive).l               ; 00600
        bsr.w   sub_009DA                       ; 00608
        clr.w   (trk_Drive).l                   ; 0060C
        bsr.w   sub_009DA                       ; 00612
        clr.w   (dat_01578).l                   ; 00616
        move.l  #ErrorTrap,(V_Trap14).w         ; 0061C
        movea.l dat_031D8(pc),a6                ; 00624
        bsr.w   sub_01260                       ; 00628
        bsr.w   EnhInit                         ; enhanced: the frames, the file cache, the title's lines
l_0062C:
        lea.l   JT_Init(pc),a7                  ; 0062C
        clr.w   (dat_030BE).l                   ; 00630
        bsr.w   sub_011AE                       ; 00636
        bsr.w   sub_0158C                       ; 00640
; (removed: the debug monitor)
;-------------------------------------------------------------------------------
; sub_009DA - MotorOff - deselects every drive, then selects trk_Drive with the motor bit off and
; deselects it: its motor stops. Keeps every register.
; Enhanced: TrackWrite / TrackRead after it are the AmigaDOS disk's (diskload.s); the monitor's
; disk commands are gone.
;-------------------------------------------------------------------------------
sub_009DA:
        ori.b   #$78,(CIAB_PRB).l               ; 009DA
        bset    #$7,(CIAB_PRB).l                ; 009E2
        move.w  d0,-(a7)                        ; 009EA
        move.w  (trk_Drive).l,d0                ; 009EC
        addq.w  #$3,d0                          ; 009F2
        bclr    d0,(CIAB_PRB).l                 ; 009F4
        bset    d0,(CIAB_PRB).l                 ; 009FA
        move.w  (a7)+,d0                        ; 00A00
        rts                                     ; 00A02
;-------------------------------------------------------------------------------
; TrackWrite / TrackRead: the AmigaDOS disk's (diskload.s)
;-------------------------------------------------------------------------------
	include	"diskload.s"
; (removed: the debug monitor)
;-------------------------------------------------------------------------------
; sub_011AE - KeyboardOn - the level 2 vector at Level2_Ports, CIA-A's serial port interrupt on
; (the keyboard), INTENA ports and master, ADKCON, DMA master + bitplanes + copper.
;-------------------------------------------------------------------------------
sub_011AE:
        lea.l   CUSTOM,a0                       ; 011AE
        move.l  #Level2_Ports,$68.l             ; 011B4
        move.b  #$7f,(CIAA_ICR).l               ; 011BE
        move.b  #$88,(CIAA_ICR).l               ; 011C6
        bclr    #$6,(CIAA_CRA).l                ; 011CE
        move.w  #$7fff,INTREQ(a0)               ; 011D6
        move.w  #$c008,INTENA(a0)               ; 011DC
        move.b  (CIAA_ICR).l,d0                 ; 011E2
        move.b  (CIAA_SDR).l,d0                 ; 011E8
        move.w  #$7fff,ADKCON(a0)               ; 011EE
        move.w  #$b500,ADKCON(a0)               ; 011F4
        move.w  #$8380,DMACON(a0)               ; 011FA
        rts                                     ; 01200
; (removed: the debug monitor)
;-------------------------------------------------------------------------------
; sub_01260 - KeyBufferClear - empties the monitor's key buffer (dat_030C0).
;-------------------------------------------------------------------------------
sub_01260:
        clr.b   (dat_030C0).l                   ; 01260
        rts                                     ; 01266
; (removed: the debug monitor)
;-------------------------------------------------------------------------------
; Level2_Ports - the level 2 interrupt (CIA-A): the parallel strobe (dat_0105E), and the keyboard:
; each key's raw code read from the serial port and acknowledged, the key map (dat_03174, a bit per
; key: KeyTest, GetKey) updated, and in the monitor the character (dat_013E4, shifted with either
; Shift: dat_03180) queued (dat_030C0). Key $7F (the Help-row key mapped to $7F) breaks into the
; monitor from anywhere, saving the registers and the PC.
; Enhanced: no monitor - the break key and the character queue do nothing.
;-------------------------------------------------------------------------------
Level2_Ports:
        move.l  d0,-(a7)                        ; 012D8
        move.w  #$8,(CUSTOM+INTREQ).l           ; 012DA
        move.b  (CIAA_ICR).l,d0                 ; 012E2
        btst    #$4,d0                          ; 012E8
        beq.w   l_012F6                         ; 012EC
        st.b    (dat_0105E).l                   ; 012F0
l_012F6:
        btst    #$3,d0                          ; 012F6
        bne.w   l_01302                         ; 012FA
        move.l  (a7)+,d0                        ; 012FE
        rte                                     ; 01300
l_01302:
        movem.l d1-d3/a0-a1,-(a7)               ; 01302
        clr.w   d0                              ; 01306
        move.b  (CIAA_SDR).l,d0                 ; 01308
        bset    #$6,(CIAA_CRA).l                ; 0130E
        lea.l   dat_03174(pc),a0                ; 01316
        ror.b   #$1,d0                          ; 0131A
        not.b   d0                              ; 0131C
        bclr    #$7,d0                          ; 0131E
        beq.w   l_0138E                         ; 01322
        move.w  d0,d1                           ; 01326
        andi.w  #$7,d1                          ; 01328
        asr.w   #$3,d0                          ; 0132C
        bclr    d1,(a0,d0.w)                    ; 0132E
l_01332:
        movem.l (a7)+,d1-d3/a0-a1               ; 01332
        move.l  (a7)+,d0                        ; 01336
        bclr    #$6,(CIAA_CRA).l                ; 01338
        rte                                     ; 01340
l_01342:
        bclr    #$6,(CIAA_CRA).l                ; 01342
        bsr.w   sub_009DA                       ; 0134A
        bsr.w   sub_01260                       ; 0134E
        movem.l (a7)+,d0-d3/a0-a1               ; 01352
        tst.w   (dat_030BE).l                   ; 01356
        bne.w   l_0062C                         ; 0135C
        tst.w   (dat_030BC).l                   ; 01360
        bne.w   l_01388                         ; 01366
        movem.l d0-d7/a0-a7,(dat_03186).l       ; 0136A
        move.w  (a7)+,(dat_031DC).l             ; 01372
        move.l  (a7)+,(dat_031D8).l             ; 01378
        movea.l (dat_031D8).l,a6                ; 0137E
        bra.w   sub_0158C                       ; 01384
l_01388:
        move.w  (a7)+,sr                        ; 01388
        bsr.w   sub_0158C                       ; 0138A
l_0138E:
        lea.l   dat_013E4(pc),a1                ; 0138E
        btst    #$0,dat_03180(pc)               ; 01392
        bne.w   l_013A6                         ; 01398
        btst    #$1,dat_03180(pc)               ; 0139C
        beq.w   l_013AA                         ; 013A2
l_013A6:
        lea.l   $80(a1),a1                      ; 013A6
l_013AA:
        move.w  d0,d1                           ; 013AA
        move.b  (a1,d0.w),d3                    ; 013AC
        beq.w   l_013D6                         ; 013B0
        cmp.b   #$7f,d3                         ; 013B4
        beq.w   l_01342                         ; 013B8
        clr.w   d2                              ; 013BC
        lea.l   dat_030C0(pc),a1                ; 013BE
        move.b  (a1),d2                         ; 013C2
        cmp.b   #$10,d2                         ; 013C4
        bcc.w   l_013D6                         ; 013C8
        lea.l   dat_030C0(pc),a1                ; 013CC
        move.b  d3,$1(a1,d2.w)                  ; 013D0
        addq.b  #$1,(a1)                        ; 013D4
l_013D6:
        asr.w   #$3,d0                          ; 013D6
        andi.w  #$7,d1                          ; 013D8
        bset    d1,(a0,d0.w)                    ; 013DC
        bra.w   l_01332                         ; 013E0
dat_013E4:
	dc.b	'`1234567890-='
	dc.b	$5C,$00
	dc.b	'0qwertyuiop[]'
	dc.b	$00
	dc.b	'123asdfghjkl'
	dc.b	$3B,$27,$00,$00,$34,$35,$36,$00
	dc.b	'zxcvbnm,./'
	dc.b	$00,$2E,$37,$38,$39,$20,$08,$09,$0D,$0D,$1B,$7F,$00,$00,$00,$00
	dc.b	$00,$01,$03,$02,$04
	dcb.b	48,$00
	dc.b	'~!@#$%^&*()_+|'
	dc.b	$00
	dc.b	'0QWERTYUIOP{}'
	dc.b	$00
	dc.b	'123ASDFGHJKL:"'
	dc.b	$00,$00,$34,$35,$36,$00
	dc.b	'ZXCVBNM<>?'
	dc.b	$00,$2C,$37,$38,$39,$20,$08,$09,$0D,$0D,$1B,$7F,$00,$00,$00,$00
	dc.b	$00,$01,$03,$02,$04
	dcb.b	48,$00
	dc.b	$48,$E7,$C0,$80,$41,$FA,$1C,$8A,$70,$03,$42,$81,$82,$98,$51,$C8
	dc.b	$FF,$FC,$4A,$81,$67,$00,$FF,$EE,$4C,$DF,$01,$03,$4E,$75
; (removed: the debug monitor)
dat_01578:
	dc.b	$00,$00
dat_0105E:                                      ; (set by the keyboard interrupt: CIA-A's FLG)
	dc.b	$00,$00

;-------------------------------------------------------------------------------
; sub_0158C - MonGo - jumps to mon_GoAddress ($4000: GameStart, unless the G command changed it),
; the monitor flags cleared. Every exception vector points here at start-up, so any exception
; restarts the game. (dat_015A8 - dat_015B8: the monitor commands' last addresses.)
;-------------------------------------------------------------------------------
sub_0158C:
        move.l  (mon_GoAddress).l,d0            ; 0158C
l_01592:
        movea.l d0,a0                           ; 01592
        move.l  d0,(mon_GoAddress).l            ; 01594
        clr.w   (dat_030BC).l                   ; 0159A
        clr.w   (dat_030BE).l                   ; 015A0
        jmp     (a0)                            ; 015A6
dat_015A8:
	dc.b	$00,$00,$40,$00
dat_015AC:
	dc.b	$00,$00,$40,$00
mon_GoAddress:
	dc.b	$00,$00,$40,$00
dat_015B4:
	dc.b	$00,$00,$20,$00
dat_015B8:
	dc.b	$00,$07,$00,$00
; (removed: the debug monitor)
;-------------------------------------------------------------------------------
; UnusedInterrupt - every interrupt autovector at start-up: "Uninitialised interrupt" and the
; monitor.
; Enhanced: the monitor is gone - this falls into ErrorTrap.
;-------------------------------------------------------------------------------
UnusedInterrupt:

;-------------------------------------------------------------------------------
; ErrorTrap - trap #14: "TRAP #14" and the monitor (the message after the trap is the caller's);
; sets dat_01578.
; Enhanced: the monitor is gone - the screen turns red and the game restarts (sub_0158C, as every
; exception).
;-------------------------------------------------------------------------------
ErrorTrap:
        move.w  #$f00,(CUSTOM+COLOR00).l        ; enhanced: the monitor is gone
        st.b    (dat_01578).l
        bra.w   sub_0158C                       ; restart the game (as every exception)

;-------------------------------------------------------------------------------
; ReadJoystick - port 2 (JOY1DAT) -> d0 (and dat_03184): bit 0 down, 1 right, 2 up, 3 left (the
; quadrature decoded), bit 7 the fire button (CIA-A PRA bit 7, low when pressed). The vertical
; blank calls it through the jump table and keeps it at $63DB0.
; Enhanced: EnhJoy after the read - the title menu's input setting (menu.s: jump on up, on button
; 2, or button 1 jumps and 2 fires).
;-------------------------------------------------------------------------------
ReadJoystick:
        move.l  d2,-(a7)                        ; 02A6C
        move.w  (CUSTOM+JOY1DAT).l,d0           ; 02A6E
        andi.w  #$303,d0                        ; 02A74
        move.w  d0,d2                           ; 02A78
        lsr.w   #$1,d2                          ; 02A7A
        andi.w  #$101,d2                        ; 02A7C
        eor.w   d2,d0                           ; 02A80
        move.w  d0,d2                           ; 02A82
        lsr.w   #$6,d2                          ; 02A84
        andi.w  #$3,d0                          ; 02A86
        or.w    d2,d0                           ; 02A8A
        move.w  d0,(dat_03184).l                ; 02A8C
        btst    #$7,(CIAA_PRA).l                ; 02A92
        bne.b   l_02AA0                         ; 02A9A
        bset    #$7,d0                          ; 02A9C
l_02AA0:
        bsr.w   EnhJoy                          ; enhanced: the input setting (menu.s)
        move.w  d0,(dat_03184).l                ; 02AA0
        move.l  (a7)+,d2                        ; 02AA6
        rts                                     ; 02AA8

;-------------------------------------------------------------------------------
; GetKey - the lowest-numbered key held (dat_03174's bits) -> d0 = its character (dat_013E4, the
; shifted table when a Shift is held; high word: the raw code), Z set if none.
;-------------------------------------------------------------------------------
GetKey:
        movem.l d1/a0,-(a7)                     ; 02AAA
        moveq   #$0,d0                          ; 02AAE
        lea.l   dat_03174(pc),a0                ; 02AB0
        moveq   #$f,d1                          ; 02AB4
l_02AB6:
        tst.b   (a0)+                           ; 02AB6
        bne.w   l_02ACA                         ; 02AB8
        addq.w  #$8,d0                          ; 02ABC
        dbra    d1,l_02AB6                      ; 02ABE
        movem.l (a7)+,d1/a0                     ; 02AC2
        clr.w   d0                              ; 02AC6
        rts                                     ; 02AC8
l_02ACA:
        move.b  -(a0),d1                        ; 02ACA
l_02ACC:
        lsr.b   #$1,d1                          ; 02ACC
        bcs.w   l_02AD8                         ; 02ACE
        addq.w  #$1,d0                          ; 02AD2
        bra.w   l_02ACC                         ; 02AD4
l_02AD8:
        move.w  d0,d1                           ; 02AD8
        swap    d0                              ; 02ADA
        lea.l   dat_013E4(pc),a1                ; 02ADC
        btst    #$0,dat_03180(pc)               ; 02AE0
        bne.w   l_02AF4                         ; 02AE6
        btst    #$1,dat_03180(pc)               ; 02AEA
        beq.w   l_02AF8                         ; 02AF0
l_02AF4:
        lea.l   $80(a1),a1                      ; 02AF4
l_02AF8:
        move.b  (a1,d1.w),d0                    ; 02AF8
        swap    d0                              ; 02AFC
        movem.l (a7)+,d1/a0                     ; 02AFE
        tst.w   d0                              ; 02B02
        rts                                     ; 02B04

;-------------------------------------------------------------------------------
; KeyTest - d0 = a raw key code -> d0 = -1 and Z clear if it is held (dat_03174, kept by the level
; 2 interrupt), 0 and Z set if not.
; Enhanced: the monitor's variables after it are gone; the enhanced code (enhanced.s and the files
; it includes) fills the space up to block 1's end.
;-------------------------------------------------------------------------------
KeyTest:
        movem.l d1/a0,-(a7)                     ; 02B06
        lea.l   dat_03174(pc),a0                ; 02B0A
        move.b  d0,d1                           ; 02B0E
        lsr.b   #$3,d0                          ; 02B10
        andi.b  #$f,d0                          ; 02B12
        andi.b  #$7,d1                          ; 02B16
        lea.l   dat_03174(pc),a0                ; 02B1A
        btst    d1,(a0,d0.w)                    ; 02B1E
        beq.b   l_02B28                         ; 02B22
        moveq   #-1,d0                          ; 02B24
        bra.b   l_02B2A                         ; 02B26
l_02B28:
        clr.l   d0                              ; 02B28
l_02B2A:
        movem.l (a7)+,d1/a0                     ; 02B2A
        tst.w   d0                              ; 02B2E
        rts                                     ; 02B30
