l_04E10:
        tst.l   (a0)                            ; 04E10
        beq.b   l_04E1C                         ; 04E12
        addq.w  #$1,d0                          ; 04E14
        lea.l   $10(a0),a0                      ; 04E16
        bra.b   l_04E10                         ; 04E1A
l_04E1C:
        addq.w  #$1,d0                          ; 04E1C
        move.w  d0,$88(a6)                      ; 04E1E
        lea.l   $10(a0),a0                      ; 04E22
        move.l  a0,$84(a6)                      ; 04E26
        lea.l   -$20(a0),a0                     ; 04E2A
