        or.w    $6(a1),d0                       ; 04E5C
        or.w    $8(a1),d0                       ; 04E60
        or.w    (a1),d0                         ; 04E64
        cmp.w   (a1),d0                         ; 04E66
        bne.w   l_04E90                         ; 04E68
        lea.l   $a(a1),a1                       ; 04E6C
        dbra    d6,l_04E54                      ; 04E70
        swap    d7                              ; 04E74
        dbra    d7,l_04E50                      ; 04E76
        lea.l   (dat_4CAA6).l,a0                ; 04E7A
        lea.l   (dat_3CAA6).l,a2                ; 04E80
