;-------------------------------------------------------------------------------
; sub_0507E - Byte-run unpack (ILBM-style: n >= 0 copies n+1 bytes, n < 0 repeats the next byte
; -n+1 times, $80 does nothing): a0 = the packed picture, a1 = where. The bytes go out through
; sub_050B4.
;-------------------------------------------------------------------------------
sub_0507E:
        movea.l a1,a2                           ; 0507E
        moveq   #$0,d5                          ; 05080
        move.l  d5,d6                           ; 05082
        move.l  d6,d7                           ; 05084
l_05086:
        move.b  (a0)+,d0                        ; 05086
        bpl.w   l_050A4                         ; 05088
        cmp.b   #$80,d0                         ; 0508C
        beq.b   l_05086                         ; 05090
        neg.b   d0                              ; 05092
        andi.w  #$7f,d0                         ; 05094
        move.b  (a0)+,d1                        ; 05098
l_0509A:
        bsr.w   sub_050B4                       ; 0509A
        dbra    d0,l_0509A                      ; 0509E
        bra.b   l_05086                         ; 050A2
l_050A4:
        andi.w  #$7f,d0                         ; 050A4
l_050A8:
