        bsr.w   sub_050B4                       ; 050AA
        dbra    d0,l_050A8                      ; 050AE
        bra.b   l_05086                         ; 050B2

;-------------------------------------------------------------------------------
; sub_050B4 - sub_0507E's output: a byte stored; the interleaved ILBM lines ($28 bytes a plane
; line, 4 planes) put into separate planes $2000 apart; after 200 lines it returns past sub_0507E
; (addq.l #4,a7): the end of the picture.
;-------------------------------------------------------------------------------
sub_050B4:
        move.b  d1,(a1)+                        ; 050B4
        bchg    #$f,d5                          ; 050B6
        beq.w   l_050F2                         ; 050BA
        addq.b  #$2,d5                          ; 050BE
        cmp.b   #$28,d5                         ; 050C0
        bne.w   l_050F2                         ; 050C4
        clr.b   d5                              ; 050C8
        lea.l   $2000(a2),a2                    ; 050CA
        movea.l a2,a1                           ; 050CE
        addi.b  #$1,d6                          ; 050D0
        andi.b  #$3,d6                          ; 050D4
        bne.w   l_050F2                         ; 050D8
        adda.l  #$ffff8028,a2                   ; 050DC
        movea.l a2,a1                           ; 050E2
        addi.b  #$1,d7                          ; 050E4
        cmp.b   #$c8,d7                         ; 050E8
        bne.w   l_050F2                         ; 050EC
        addq.l  #$4,a7                          ; 050F0
l_050F2:
        rts                                     ; 050F2

;-------------------------------------------------------------------------------
