;-------------------------------------------------------------------------------
; LoadTracks - read tracks of the disk through the jump table's TrackRead, 5 tries; then the "fatal
; disk error" screen (it hangs: the text asks for DEL). d0 = the first track, d1 = how many, a0 =
; where, d2 = the drive. Called at the start of each level (5 tracks of packed world data, 1 for
; the map, and on the boss levels 2 more), for the progress screen between levels (5 tracks from
; track 144) and for level 4-4's second map ($45CC). On the AmigaDOS disk, TrackRead is replaced by
; enhanced/src/diskload.s. LoadedLevel after it: the level whose data is in memory.
;-------------------------------------------------------------------------------
LoadTracks:
        move.w  #$5,$c2(a6)                     ; 055BA  d0 = track, d1 = tracks, a0 = where, d2 = drive (always DF0): 5 tries
        movem.l d0-d2/a0,$b2(a6)                ; 055C0
l_055C6:
        movem.l $b2(a6),d0-d2/a0                ; 055C6
        jsr     (JT_TrackRead).l                ; 055CC  the track reader (TrackRead)
        tst.w   d0                              ; 055D2
        bpl.b   l_055EE                         ; 055D4
        subq.w  #$1,$c2(a6)                     ; 055D6
        bne.b   l_055C6                         ; 055DA
        lea.l   GamePalette(pc),a0              ; 055DC
        bsr.w   SetPalette                      ; 055E0
        lea.l   DiskErrorText(pc),a0            ; 055E4
        bsr.w   sub_0C6A8                       ; 055E8
l_055EC:
        bra.b   l_055EC                         ; 055EC  a fatal disk error: hangs (the text asks for DEL)
l_055EE:
        rts                                     ; 055EE
DiskErrorText:
	dc.b	$04,$00,$01,$00,$02,$0F
	dc.b	'THERE HAS BEEN A FATAL DISK ERROR'
	dc.b	$00,$04,$10
	dc.b	'PLEASE CHECK THE DISK &'
	dc.b	$00,$04,$18
	dc.b	'PRESS THE '
	dc.b	$27,$44,$45,$4C,$27,$20,$4B,$45,$59,$2E,$FF,$00
LoadedLevel:
	dc.b	$FF,$FF

;-------------------------------------------------------------------------------
; UnpackLevel - a level's packed world data unpacked in place: a0 = the data (long: unpacked
; length, long: packed length, then the packed bytes). The packed bytes are first moved to the top
; of the space, then unpacked forwards: a marker byte (the first), then bytes copied; marker, byte,
; count repeats the byte count + 1 times.
;-------------------------------------------------------------------------------
UnpackLevel:
        movem.l d0-d3/a0-a2,-(a7)               ; 0564C
        move.l  a0,-(a7)                        ; 05650
        movea.l a0,a1                           ; 05652
        move.l  (a1)+,d3                        ; 05654
        move.l  (a1)+,d1                        ; 05656
        adda.l  d1,a1                           ; 05658
        addq.l  #$1,a1                          ; 0565A
        adda.l  d3,a0                           ; 0565C
        addq.l  #$1,a0                          ; 0565E
l_05660:
        move.b  -(a1),-(a0)                     ; 05660
        subq.l  #$1,d1                          ; 05662
        bpl.b   l_05660                         ; 05664
        exg.l   a1,a0                           ; 05666
        movea.l (a7)+,a0                        ; 05668
        move.b  (a1)+,d2                        ; 0566A
l_0566C:
        move.b  (a1)+,d0                        ; 0566C
        cmp.b   d0,d2                           ; 0566E
        beq.b   l_0567A                         ; 05670
        move.b  d0,(a0)+                        ; 05672
        subq.l  #$1,d3                          ; 05674
        bpl.b   l_0566C                         ; 05676
        bra.b   l_0568C                         ; 05678
l_0567A:
        clr.w   d1                              ; 0567A
        move.b  (a1)+,d0                        ; 0567C
        move.b  (a1)+,d1                        ; 0567E
l_05680:
        move.b  d0,(a0)+                        ; 05680
        subq.l  #$1,d3                          ; 05682
        dbra    d1,l_05680                      ; 05684
        tst.l   d3                              ; 05688
        bpl.b   l_0566C                         ; 0568A
l_0568C:
        movem.l (a7)+,d0-d3/a0-a2               ; 0568C
        rts                                     ; 05690

;-------------------------------------------------------------------------------
; StopSample (unreferenced) - channel 3 stopped and the sample's state cleared ($98, $A4, $40(a6)).
