;-------------------------------------------------------------------------------
; PlaySample - play a sound effect: a0 = an IFF 8SVX file (FORM). Finds VHDR and BODY, period =
; 3579546 / samples per second, and plays it on channel 3; the level 4 interrupt (Level4_Sample)
; sets the repeat. The effects are IFF 8SVX files saved with Audio Master (tools/assets/sound.py
; extracts them).
;-------------------------------------------------------------------------------
PlaySample:
        movem.l a4-a5,-(a7)                     ; 056A8
        lea.l   CUSTOM,a5                       ; 056AC
        move.w  #$ff,ADKCON(a5)                 ; 056B2
        move.w  #$400,INTENA(a5)                ; 056B8
        move.w  #$8,DMACON(a5)                  ; 056BE
        st.b    $40(a6)                         ; 056C4
l_056C8:
        cmpi.w  #$5648,(a0)+                    ; 056C8
        bne.b   l_056C8                         ; 056CC
        cmpi.w  #$4452,(a0)                     ; 056CE
        bne.b   l_056C8                         ; 056D2
        addq.l  #$6,a0                          ; 056D4
        move.l  (a0),$ac(a6)                    ; 056D6
        move.l  $4(a0),$a4(a6)                  ; 056DA
        move.l  $4(a0),$98(a6)                  ; 056E0
        move.l  #$369e9a,d1                     ; 056E6
        divu.w  $c(a0),d1                       ; 056EC
l_056F0:
        cmpi.w  #$424f,(a0)+                    ; 056F0
        bne.b   l_056F0                         ; 056F4
        cmpi.w  #$4459,(a0)                     ; 056F6
        bne.b   l_056F0                         ; 056FA
        addq.l  #$6,a0                          ; 056FC
        move.l  a0,$a8(a6)                      ; 056FE
        adda.l  $ac(a6),a0                      ; 05702
        move.l  a0,$a0(a6)                      ; 05706
        move.l  a0,$9c(a6)                      ; 0570A
        movea.l $a8(a6),a0                      ; 0570E
        move.l  $ac(a6),d0                      ; 05712
        bne.b   l_05720                         ; 05716
        movea.l $a0(a6),a0                      ; 05718
        move.l  $a4(a6),d0                      ; 0571C
l_05720:
        move.l  a0,$d0(a5)                      ; 05720
        asr.l   #$1,d0                          ; 05724
        move.w  d0,$d4(a5)                      ; 05726
        move.w  d1,$d6(a5)                      ; 0572A
        move.l  #Level4_Sample,(V_Level4).w     ; 0572E
        move.w  #$7f,$d8(a5)                    ; 05736
        moveq   #$2,d0                          ; 0573C
        move.w  $6(a5),d1                       ; 0573E
        andi.w  #$ff00,d1                       ; 05742
l_05746:
