        move.w  d2,d1                           ; 05752
        dbra    d0,l_05746                      ; 05754
        move.w  #$8008,$96(a5)                  ; 05758
        clr.w   (dat_05776).l                   ; 0575E
        move.w  #$400,$9c(a5)                   ; 05764
        move.w  #$8400,$9a(a5)                  ; 0576A
        movem.l (a7)+,a4-a5                     ; 05770
        rts                                     ; 05774
dat_05776:
	dc.b	$00,$00

;-------------------------------------------------------------------------------
; Level4_Sample - the level 4 interrupt (audio 3) for PlaySample: the first interrupt only marks
; dat_05776; the next sets the repeat (a looped sample's repeat part: $A0/$A4(a6)) or, for a
; one-shot, turns the interrupt and channel 3 off.
;-------------------------------------------------------------------------------
Level4_Sample:
        movem.l d0/a6,-(a7)                     ; 05778
        tst.w   (dat_05776).l                   ; 0577C
        bne.b   l_0578C                         ; 05782
        st.b    (dat_05776).l                   ; 05784
        bra.b   l_057B8                         ; 0578A
l_0578C:
        lea.l   (mem_641B8).l,a6                ; 0578C
        move.l  $a4(a6),d0                      ; 05792
        beq.b   l_057C6                         ; 05796
        move.w  #$8,(CUSTOM+DMACON).l           ; 05798
        move.l  $a0(a6),(CUSTOM+AUD3LCH).l      ; 057A0
