;-------------------------------------------------------------------------------
; Music_Init - the music driver started: Music_InitInstruments. Music_Stop, Music_Start, Music_Play
; after it are its other entry points (the driver is Jonathan Dunn's: docs/SOUND.md).
;-------------------------------------------------------------------------------
Music_Init:
        bra.w   Music_InitInstruments           ; 0E800

;-------------------------------------------------------------------------------
; Music_Stop - d0 = a song: its voices stopped (l_0E9D6); 0 or out of range: all.
;-------------------------------------------------------------------------------
Music_Stop:
        bra.w   l_0E9D6                         ; 0E804

;-------------------------------------------------------------------------------
; Music_Start - d0 = a song (1-12): Music_StartSong.
;-------------------------------------------------------------------------------
Music_Start:
        bra.w   Music_StartSong                 ; 0E808

;-------------------------------------------------------------------------------
; Music_Play - once a frame from the vertical blank: Music_Frame. The voices' state follows
; (Music_Voice0-2, 86 bytes each, and a fourth block, dat_0E92A).
;-------------------------------------------------------------------------------
Music_Play:
        bra.w   Music_Frame                     ; 0E80C
Music_Voices:
	dc.b	$00,$00
dat_0E812:
	dc.b	$01
dat_0E813:
	dc.b	$01
dat_0E814:
	dc.b	$FF,$FF
dat_0E816:
	dc.b	$FF,$FF,$FF,$FF,$00,$00,$00,$00,$FF,$FF
	dc.b	$00
	dc.b	$00
	dc.b	$00
	dc.b	$00
dat_0E824:
	dc.b	$00
	dc.b	$00
Music_Trigger:
	dc.b	$00
	dc.b	$00
Music_Voice0:
	dcb.b	85,$00
	dc.b	$01
Music_Voice1:
	dcb.b	85,$00
	dc.b	$02
Music_Voice2:
	dcb.b	85,$00
	dc.b	$04
dat_0E92A:
	dcb.b	85,$00
	dc.b	$08

;-------------------------------------------------------------------------------
; sub_0E980 - All the voices silenced: their state reset (sub_0E9B6 four times) and Paula's volumes
; 0, the playing flags (Music_Voices) cleared.
;-------------------------------------------------------------------------------
sub_0E980:
        movem.l d0/a0-a1,-(a7)                  ; 0E980
        move.b  #$0,(dat_0E812).l               ; 0E984
        move.b  #$0,(dat_0E813).l               ; 0E98C
        lea.l   (Music_Voice0).l,a0             ; 0E994
        lea.l   (CUSTOM+AUD0VOL).l,a1           ; 0E99A
        bsr.b   sub_0E9B6                       ; 0E9A0
        bsr.b   sub_0E9B6                       ; 0E9A2
        bsr.b   sub_0E9B6                       ; 0E9A4
        bsr.b   sub_0E9B6                       ; 0E9A6
        move.w  #$0,(Music_Voices).l            ; 0E9A8
        movem.l (a7)+,d0/a0-a1                  ; 0E9B0
        rts                                     ; 0E9B4

;-------------------------------------------------------------------------------
; sub_0E9B6 - One voice reset (a0 = its state, a1 = its audio registers), and on to the next.
; l_0E9D6 (Music_Stop): the voices a song uses reset.
;-------------------------------------------------------------------------------
sub_0E9B6:
        move.w  #$0,$0(a0)                      ; 0E9B6
        move.w  #$1,$4a(a0)                     ; 0E9BC
        move.w  #$0,$4c(a0)                     ; 0E9C2
        move.w  #$0,(a1)                        ; 0E9C8
        adda.w  #$56,a0                         ; 0E9CC
        adda.w  #$10,a1                         ; 0E9D0
        rts                                     ; 0E9D4
l_0E9D6:
        movem.l d0/d7/a0-a2,-(a7)               ; 0E9D6
        subq.w  #$1,d0                          ; 0E9DA
        bmi.b   l_0E9E4                         ; 0E9DC
        cmp.w   #$c,d0                          ; 0E9DE
        bcs.b   l_0E9EA                         ; 0E9E2
l_0E9E4:
        bsr.w   sub_0E980                       ; 0E9E4
        bra.b   l_0EA16                         ; 0E9E8
l_0E9EA:
        lea.l   (Music_Songs).l,a2              ; 0E9EA
        asl.w   #$3,d0                          ; 0E9F0
        adda.w  d0,a2                           ; 0E9F2
        lea.l   (Music_Voice0).l,a0             ; 0E9F4
        lea.l   (CUSTOM+AUD0VOL).l,a1           ; 0E9FA
        moveq   #$2,d7                          ; 0EA00
l_0EA02:
        tst.w   (a2)+                           ; 0EA02
        bne.b   l_0EA10                         ; 0EA04
        adda.w  #$56,a0                         ; 0EA06
        adda.w  #$10,a1                         ; 0EA0A
        bra.b   l_0EA12                         ; 0EA0E
l_0EA10:
        bsr.b   sub_0E9B6                       ; 0EA10
l_0EA12:
        dbra    d7,l_0EA02                      ; 0EA12
l_0EA16:
        movem.l (a7)+,d0/d7/a0-a2               ; 0EA16
        rts                                     ; 0EA1A

;-------------------------------------------------------------------------------
; Music_StartLow - A song started at low priority (unreferenced): flag $4000 rather than $8000,
; only if the fourth block is free or the song is not lower than the one there (dat_0E813).
;-------------------------------------------------------------------------------
Music_StartLow:		; (no references found: found by the code sweep)
        tst.w   (dat_0E92A).l                   ; 0EA1C
        beq.b   l_0EA2C                         ; 0EA22
        cmp.b   (dat_0E813).l,d0                ; 0EA24
        bcs.b   l_0EA3C                         ; 0EA2A
l_0EA2C:
        movem.l d0/d7/a0-a2,-(a7)               ; 0EA2C
        move.w  #$4000,d1                       ; 0EA30
        move.b  d0,(dat_0E813).l                ; 0EA34
        bra.b   l_0EA4C                         ; 0EA3A
l_0EA3C:
        rts                                     ; 0EA3C

;-------------------------------------------------------------------------------
; Music_StartSong - d0 = the song (1-12; else all stopped): for each of its three voices
; (Music_Songs: an offset each, 0 none) the order list is read - $80 the end (back to the mark, or
; the voice stops), $81 the mark, $82 n a transpose, $83 n a repeat count; then the first pattern
; (Music_Patterns). The voice's flags: $8000 playing.
;-------------------------------------------------------------------------------
Music_StartSong:
        movem.l d0/d7/a0-a2,-(a7)               ; 0EA3E
        move.w  #$8000,d1                       ; 0EA42
        move.b  d0,(dat_0E812).l                ; 0EA46
l_0EA4C:
        clr.w   (dat_0E824).l                   ; 0EA4C
        subq.w  #$1,d0                          ; 0EA52
        bmi.b   l_0EA5C                         ; 0EA54
        cmp.w   #$c,d0                          ; 0EA56
        bcs.b   l_0EA64                         ; 0EA5A
l_0EA5C:
        bsr.w   sub_0E980                       ; 0EA5C
        bra.w   l_0EAFC                         ; 0EA60
l_0EA64:
        lea.l   (Music_Songs).l,a0              ; 0EA64
        asl.w   #$3,d0                          ; 0EA6A
        adda.w  d0,a0                           ; 0EA6C
        lea.l   (Music_Voice0).l,a1             ; 0EA6E
        moveq   #$2,d7                          ; 0EA74
l_0EA76:
        move.w  (a0)+,d0                        ; 0EA76
        beq.b   l_0EAEE                         ; 0EA78
        lea.l   -$2(a0,d0.w),a2                 ; 0EA7A
        moveq   #$0,d0                          ; 0EA7E
        move.w  d0,$4c(a1)                      ; 0EA80
        move.l  d0,$2(a1)                       ; 0EA84
        move.l  d0,$a(a1)                       ; 0EA88
        move.b  d0,$13(a1)                      ; 0EA8C
        move.b  #$1,$12(a1)                     ; 0EA90
        move.w  d1,$0(a1)                       ; 0EA96
l_0EA9A:
        move.b  (a2)+,d0                        ; 0EA9A
        bpl.b   l_0EAD2                         ; 0EA9C
        subi.b  #$80,d0                         ; 0EA9E
        bne.b   l_0EAB4                         ; 0EAA2
        movea.l $2(a1),a2                       ; 0EAA4
        cmpa.w  #$0,a2                          ; 0EAA8
        bne.b   l_0EA9A                         ; 0EAAC
        clr.w   $0(a1)                          ; 0EAAE
        bra.b   l_0EAEE                         ; 0EAB2
l_0EAB4:
        subq.b  #$1,d0                          ; 0EAB4
        bne.b   l_0EABE                         ; 0EAB6
        move.l  a2,$2(a1)                       ; 0EAB8
        bra.b   l_0EA9A                         ; 0EABC
l_0EABE:
        subq.b  #$1,d0                          ; 0EABE
        bne.b   l_0EAC8                         ; 0EAC0
        move.b  (a2)+,$13(a1)                   ; 0EAC2
        bra.b   l_0EA9A                         ; 0EAC6
l_0EAC8:
        subq.b  #$1,d0                          ; 0EAC8
        bne.b   l_0EA9A                         ; 0EACA
        move.b  (a2)+,$12(a1)                   ; 0EACC
        bra.b   l_0EA9A                         ; 0EAD0
l_0EAD2:
        move.l  a2,$6(a1)                       ; 0EAD2
        lea.l   (Music_Patterns).l,a2           ; 0EAD6
        ext.w   d0                              ; 0EADC
        add.w   d0,d0                           ; 0EADE
        adda.w  d0,a2                           ; 0EAE0
        adda.w  (a2),a2                         ; 0EAE2
        move.l  a2,$e(a1)                       ; 0EAE4
        move.w  #$1,$52(a1)                     ; 0EAE8
l_0EAEE:
        lea.l   $56(a1),a1                      ; 0EAEE
        dbra    d7,l_0EA76                      ; 0EAF2
        or.w    d1,(Music_Voices).l             ; 0EAF6
l_0EAFC:
        movem.l (a7)+,d0/d7/a0-a2               ; 0EAFC
        rts                                     ; 0EB00

;-------------------------------------------------------------------------------
; Music_Frame - each voice that plays (Music_Voice), then Paula written (Music_Output).
;-------------------------------------------------------------------------------
Music_Frame:
        lea.l   CUSTOM,a6                       ; 0EB02
        lea.l   (Music_Periods).l,a5            ; 0EB08
        clr.w   (Music_Trigger).l               ; 0EB0E
        tst.w   (Music_Voices).l                ; 0EB14
        beq.b   l_0EB6A                         ; 0EB1A
        addq.w  #$1,(dat_0E824).l               ; 0EB1C
        lea.l   (Music_Voice0).l,a4             ; 0EB22
        move.w  $0(a4),d7                       ; 0EB28
        beq.b   l_0EB3A                         ; 0EB2C
        bsr.b   Music_Voice                     ; 0EB2E
        move.w  d7,$0(a4)                       ; 0EB30
        move.w  d7,(Music_Voices).l             ; 0EB34
l_0EB3A:
        lea.l   (Music_Voice1).l,a4             ; 0EB3A
        move.w  $0(a4),d7                       ; 0EB40
        beq.b   l_0EB52                         ; 0EB44
        bsr.b   Music_Voice                     ; 0EB46
        move.w  d7,$0(a4)                       ; 0EB48
        or.w    d7,(Music_Voices).l             ; 0EB4C
l_0EB52:
        lea.l   (Music_Voice2).l,a4             ; 0EB52
        move.w  $0(a4),d7                       ; 0EB58
        beq.b   l_0EB6A                         ; 0EB5C
        bsr.b   Music_Voice                     ; 0EB5E
        move.w  d7,$0(a4)                       ; 0EB60
        or.w    d7,(Music_Voices).l             ; 0EB64
l_0EB6A:
        andi.w  #$c000,(Music_Voices).l         ; 0EB6A
        bsr.w   Music_Output                    ; 0EB72
        rts                                     ; 0EB76

;-------------------------------------------------------------------------------
; Music_Voice - one voice, a frame (a4 = its state, d7 its flags): when its note runs out the
; pattern is read - commands $80-$90 (dat_0EBAE) and a note (Music_Periods, less the instrument's
; base note, plus the transpose; then its length unless fixed) - and every frame the effects
; (slide, trill, arpeggio, vibrato) and the volume envelope.
;-------------------------------------------------------------------------------
Music_Voice:
        subq.w  #$1,$52(a4)                     ; 0EB78
        bne.w   l_0EE60                         ; 0EB7C
        movea.l $e(a4),a3                       ; 0EB80
        bclr    #$7,d7                          ; 0EB84
l_0EB88:
        move.b  (a3)+,d0                        ; 0EB88
        bpl.w   l_0ED72                         ; 0EB8A
        bclr    #$3,d7                          ; 0EB8E
        cmp.b   #$a0,d0                         ; 0EB92
        bcc.b   l_0EB88                         ; 0EB96
        lea.l   dat_0EBAE(pc),a0                ; 0EB98
        subi.b  #$80,d0                         ; 0EB9C
        ext.w   d0                              ; 0EBA0
        add.w   d0,d0                           ; 0EBA2
        adda.w  d0,a0                           ; 0EBA4
        move.w  (a0),d0                         ; 0EBA6
        beq.b   l_0EB88                         ; 0EBA8
        jmp     (a0,d0.w)                       ; 0EBAA
dat_0EBAE:
        dc.w    sub_0EBEE-*                     ; 0EBAE
        dc.w    sub_0EC6C-*                     ; 0EBB0
        dc.w    sub_0EC74-*                     ; 0EBB2
        dc.w    sub_0EC78-*                     ; 0EBB4
        dc.w    sub_0EC7C-*                     ; 0EBB6
        dc.w    sub_0EC88-*                     ; 0EBB8
        dc.w    sub_0EC90-*                     ; 0EBBA
        dc.w    sub_0EC9A-*                     ; 0EBBC
        dc.w    sub_0ECAA-*                     ; 0EBBE
        dc.w    sub_0ECBA-*                     ; 0EBC0
        dc.w    sub_0ECCE-*                     ; 0EBC2
        dc.w    sub_0ED06-*                     ; 0EBC4
        dc.w    sub_0ED1E-*                     ; 0EBC6
        dc.w    sub_0ECD6-*                     ; 0EBC8
        dc.w    sub_0ECFE-*                     ; 0EBCA
        dc.w    sub_0ED26-*                     ; 0EBCC
        dc.w    sub_0ED3E-*                     ; 0EBCE
        dc.w    0                               ; 0EBD0
        dc.w    0                               ; 0EBD2
        dc.w    0                               ; 0EBD4
        dc.w    0                               ; 0EBD6
        dc.w    0                               ; 0EBD8
        dc.w    0                               ; 0EBDA
        dc.w    0                               ; 0EBDC
        dc.w    0                               ; 0EBDE
        dc.w    0                               ; 0EBE0
        dc.w    0                               ; 0EBE2
        dc.w    0                               ; 0EBE4
        dc.w    0                               ; 0EBE6
        dc.w    0                               ; 0EBE8
        dc.w    0                               ; 0EBEA
        dc.w    0                               ; 0EBEC

;-------------------------------------------------------------------------------
; sub_0EBEE - Pattern command $80: the pattern's end - the next from the order list ($80-$83 as in
; Music_StartSong; the order list's end with no mark stops the voice), or back to the pattern loop
; ($81) if set.
;-------------------------------------------------------------------------------
sub_0EBEE:
        movea.l $a(a4),a3                       ; 0EBEE
        cmpa.w  #$0,a3                          ; 0EBF2
        bne.w   l_0EB88                         ; 0EBF6
        movea.l $6(a4),a3                       ; 0EBFA
        move.b  -$1(a3),d0                      ; 0EBFE
        subq.b  #$1,$12(a4)                     ; 0EC02
        bne.b   l_0EC56                         ; 0EC06
        move.b  #$1,$12(a4)                     ; 0EC08
        move.b  #$0,$13(a4)                     ; 0EC0E
l_0EC14:
        move.b  (a3)+,d0                        ; 0EC14
        bpl.b   l_0EC56                         ; 0EC16
        subi.b  #$80,d0                         ; 0EC18
        bne.b   l_0EC38                         ; 0EC1C
        movea.l $2(a4),a3                       ; 0EC1E
        cmpa.w  #$0,a3                          ; 0EC22
        bne.b   l_0EC14                         ; 0EC26
        move.w  #$1,$4a(a4)                     ; 0EC28
        move.w  #$0,$4c(a4)                     ; 0EC2E
        moveq   #$0,d7                          ; 0EC34
        rts                                     ; 0EC36
l_0EC38:
        subq.b  #$1,d0                          ; 0EC38
        bne.b   l_0EC42                         ; 0EC3A
        move.l  a3,$2(a4)                       ; 0EC3C
        bra.b   l_0EC14                         ; 0EC40
l_0EC42:
        subq.b  #$1,d0                          ; 0EC42
        bne.b   l_0EC4C                         ; 0EC44
        move.b  (a3)+,$13(a4)                   ; 0EC46
        bra.b   l_0EC14                         ; 0EC4A
l_0EC4C:
        subq.b  #$1,d0                          ; 0EC4C
        bne.b   l_0EC14                         ; 0EC4E
        move.b  (a3)+,$12(a4)                   ; 0EC50
        bra.b   l_0EC14                         ; 0EC54
l_0EC56:
        move.l  a3,$6(a4)                       ; 0EC56
        lea.l   (Music_Patterns).l,a3           ; 0EC5A
        ext.w   d0                              ; 0EC60
        add.w   d0,d0                           ; 0EC62
        adda.w  d0,a3                           ; 0EC64
        adda.w  (a3),a3                         ; 0EC66
        bra.w   l_0EB88                         ; 0EC68

;-------------------------------------------------------------------------------
; sub_0EC6C - Pattern command $81: a loop point in the pattern.
;-------------------------------------------------------------------------------
sub_0EC6C:
        move.l  a3,$a(a4)                       ; 0EC6C
        bra.w   l_0EB88                         ; 0EC70

;-------------------------------------------------------------------------------
; sub_0EC74 - Pattern command $82: nothing.
;-------------------------------------------------------------------------------
sub_0EC74:
        bra.w   l_0EB88                         ; 0EC74

;-------------------------------------------------------------------------------
; sub_0EC78 - Pattern command $83: nothing.
;-------------------------------------------------------------------------------
sub_0EC78:
        bra.w   l_0EB88                         ; 0EC78

;-------------------------------------------------------------------------------
; sub_0EC7C - Pattern command $84 n: every note n frames long from now ($51; no length bytes).
;-------------------------------------------------------------------------------
sub_0EC7C:
        bset    #$5,d7                          ; 0EC7C
        move.b  (a3)+,$51(a4)                   ; 0EC80
        bra.w   l_0EB88                         ; 0EC84

;-------------------------------------------------------------------------------
; sub_0EC88 - Pattern command $85: the notes' lengths in the stream again.
;-------------------------------------------------------------------------------
sub_0EC88:
        bclr    #$5,d7                          ; 0EC88
        bra.w   l_0EB88                         ; 0EC8C

;-------------------------------------------------------------------------------
; sub_0EC90 - Pattern command $86: 256 frames more.
;-------------------------------------------------------------------------------
sub_0EC90:
        addi.w  #$100,$52(a4)                   ; 0EC90
        bra.w   l_0EB88                         ; 0EC96

;-------------------------------------------------------------------------------
; sub_0EC9A - Pattern command $87: a rest - the voice silent (volume 0) for the length that
; follows.
;-------------------------------------------------------------------------------
sub_0EC9A:
        bclr    #$4,d7                          ; 0EC9A
        bset    #$7,d7                          ; 0EC9E
        clr.w   $4c(a4)                         ; 0ECA2
        bra.w   l_0EE4A                         ; 0ECA6

;-------------------------------------------------------------------------------
; sub_0ECAA - Pattern command $88 a b: a slide from a semitones away over b frames.
;-------------------------------------------------------------------------------
sub_0ECAA:
        bset    #$3,d7                          ; 0ECAA
