sub_0ED1E:
        bclr    #$2,d7                          ; 0ED1E
        bra.w   l_0EB88                         ; 0ED22

;-------------------------------------------------------------------------------
; sub_0ED26 - Pattern command $8F n: volume envelope n (Music_Envelopes).
